//////
/// 
/// $INTERFACE VIDENC                  biu              (4,4)
///     ###
///     * Register specification of interface VIDEO_ENCODER
///     * Defines the size of the video_encoder
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 8  E_CTRL_0                  0x0
///                                    ###
///                                    * hs0del [3:0]
///                                    * Delay on digital hsync/composite sync associated with outputs of DAC 0, 1 and 2
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 8  E_CTRL_1                  0x0
///                                    ###
///                                    * vs0del [3:0]
///                                    * Delay on digital vsync associated with outputs of DAC 0, 1 and 2
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00008 CFG2                 (P)
///               %unsigned 8  E_CTRL_2                  0x0
///                                    ###
///                                    * hs1del [3:0]
///                                    * Delay on digital hsync/composite sync associated with outputs of DAC 3, 4 and 5
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x0000C CFG3                 (P)
///               %unsigned 8  E_CTRL_3                  0x0
///                                    ###
///                                    * vs1del [3:0]
///                                    * Delay on digital vsync associated with outputs of DAC 3, 4 and 5
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00010 CFG4                 (P)
///               %unsigned 8  E_CTRL_4                  0x0
///                                    ###
///                                    * Polarity control on the DAC clocks.
///                                    * [0]: Controls the polarity of clock going to SD-DACs (DAC 0, 1 and 2)
///                                    * 0: clock polarity is not inverted.
///                                    * 1: clock polarity is inverted.
///                                    * [1]: Controls the polarity of clock going to HD-DACs (DAC 3, 4 and 5)
///                                    * 0: clock polarity is not inverted.
///                                    * 1: clock polarity is inverted.
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00014 CFG5                 (P)
///               %unsigned 8  E_CTRL_5                  0xC
///                                    ###
///                                    * [5:0] SD DAC control : Specifies the peak to peak DAC          voltage used for SD outputs for proper Macrovision signal amplitudes.
///                                    * Dac voltage = 1 + sd_vdac/40
///                                    * 0 : 1 V
///                                    * 1 : 1.025 V
///                                    * 2 : 1.05 V
///                                    * .    .     .     .
///                                    * 38 : 1.95 V
///                                    * 39 : 1.975 V
///                                    * 40 : 2.0 V
///                                    * 41 : 63: Reserved
///                                    * [7:6] SD output mode
///                                    * 0: Full 12bit mode
///                                    * 1: 9bit mode(MSB aligned)
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00018 CFG6                 (P)
///               %unsigned 8  E_CTRL_6                  0xC
///                                    ###
///                                    * [5:0] HD DAC control : Specifies the peak to peak DAC voltage used for HD outputs for proper Macrovision signal amplitudes.
///                                    * Dac voltage = 1 + hd_vdac/40
///                                    * 0 : 1 V
///                                    * 1 : 1.025 V
///                                    * 2 : 1.05 V
///                                    * . . . .
///                                    * 38 : 1.95 V
///                                    * 39 : 1.975 V
///                                    * 40 : 2.0 V
///                                    * 41 : 63: Reserved.
///                                    * [7:6] HD output mode
///                                    * 0: Full 12bit mode
///                                    * 1: 9bit mode(MSB aligned)
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x0001C CFG7                 (P)
///               %unsigned 8  E_CTRL_7                  0x0
///                                    ###
///                                    * HD CGMS Type B packet Header bits
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00020 CFG8                 (P)
///               %unsigned 8  E_CTRL_8                  0x20
///                                    ###
///                                    * dac_sel[3:0] : SD DACs
///                                    * DAC2
///                                    * DAC1
///                                    * DAC0
///                                    * 0
///                                    * SD B/Cb
///                                    * SD G/Y
///                                    * SD R/Cr
///                                    * 1
///                                    * C Svideo
///                                    * Y Svideo
///                                    * CVBS
///                                    * 2
///                                    * CVBS
///                                    * Y Svideo
///                                    * C Svideo
///                                    * 3
///                                    * CVBS
///                                    * CVBS
///                                    * CVBS
///                                    * oversample factor[7:4] :
///                                    * 0 : No oversampling (1x), 1 : 2x, 2 : 4x, 3 : 8x
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00024 CFG9                 (P)
///               %unsigned 8  E_CTRL_9                  0x24
///                                    ###
///                                    * dac_sel[3:0] : SD/HD DACs
///                                    * DAC2
///                                    * DAC1
///                                    * DAC0
///                                    * 0
///                                    * SD B/Cb
///                                    * SD G/Y
///                                    * SD R/Cr
///                                    * 1
///                                    * C Svideo
///                                    * Y Svideo
///                                    * CVBS
///                                    * 2
///                                    * CVBS
///                                    * Y Svideo
///                                    * C Svideo
///                                    * 3
///                                    * CVBS
///                                    * CVBS
///                                    * CVBS
///                                    * oversample factor[7:4] :
///                                    * 0 : No oversampling (1x), 1 : 2x, 2 : 4x, 3 : 8x
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00028 CFG10                (P)
///               %unsigned 8  E_CTRL_10                 0x59
///                                    ###
///                                    * H total [7:0] Total number of pixels between two hsyncs
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x0002C CFG11                (P)
///               %unsigned 8  E_CTRL_11                 0x3
///                                    ###
///                                    * H total [9:8] Total number of pixels between two hsyncs
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00030 CFG12                (P)
///               %unsigned 8  E_CTRL_12                 0xC
///                                    ###
///                                    * V total [7:0] Total number of progressive hsyncs between two vsyncs. All vertical resolutions are in progressive terms irrespective of progressive or interlace operating mode.
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00034 CFG13                (P)
///               %unsigned 8  E_CTRL_13                 0x2
///                                    ###
///                                    * V total [9:8] Total number of progressive hsyncs between two vsyncs. All vertical resolutions are in progressive terms irrespective of progressive or interlace operating mode.
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00038 CFG14                (P)
