/// $INTERFACE ClampMap                biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000 Ctrl                 (P)
///               ###
///               * Control registers
///               ###
///               %unsigned 1  bypass                    0x0
///                                    ###
///                                    * 1'b1: bypass ClampMap module
///                                    * 1'b0: normal work
///                                    ###
///               %unsigned 3  mode                      0x0
///                                    ###
///                                    * 3'd0:RGB444;
///                                    * 3'd1:YUV444;
///                                    * 3'd2:YUV422;
///                                    * 3'd3:YUV420P;
///                                    * 3'd4:YUV420SP;
///                                    ###
///               %unsigned 1  lsb_first                 0x0
///                                    ###
///                                    * Only available when mode = 3'd3
///                                    * 0: MSB first;
///                                    * 1: LSB first;
///                                    ###
///               %unsigned 1  uv_swap                   0x0
///                                    ###
///                                    * Only available when mode = 3'd0, 3'b1, 3'b2 or 3'b4.
///                                    * BR swap for RGB444 and UV swap for others.
///                                    * 1'd0: UV/BR un-switch
///                                    * 1'd1: UV/BR switch
///                                    ###
///               %unsigned 2  bit_depth                 0x0
///                                    ###
///                                    * 2'h0: 12-bit
///                                    * 2'h1: 10-bit
///                                    * 2'h2: 8-bit
///                                    * 2'h3: Reserve
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00004 in_min_x             (P)
///               ###
///               * Input data clamping's minimum value of x
///               ###
///               %unsigned 12 in_min_x                  0x0
///               %%        20         # Stuffing bits...
///     @ 0x00008 in_max_x             (P)
///               ###
///               * Input data clamping's maximum value of x
///               ###
///               %unsigned 12 in_max_x                  0x3FF
///               %%        20         # Stuffing bits...
///     @ 0x0000C out_min_x            (P)
///               ###
///               * output data clamping's minimum value of x
///               ###
///               %unsigned 12 out_min_x                 0x0
///               %%        20         # Stuffing bits...
///     @ 0x00010 out_max_x            (P)
///               ###
///               * output data clamping's maximum value of x
///               ###
///               %unsigned 12 out_max_x                 0x3FF
///               %%        20         # Stuffing bits...
///     @ 0x00014 ratio_x              (P)
///               ###
///               * Multiplication factor in mapping of x
///               ###
///               %unsigned 14 ratio_x                   0x400
///               %%        18         # Stuffing bits...
///     @ 0x00018 in_min_y             (P)
///               ###
///               * Input data clamping's minimum value of y
///               ###
///               %unsigned 12 in_min_y                  0x0
///               %%        20         # Stuffing bits...
///     @ 0x0001C in_max_y             (P)
///               ###
///               * Input data clamping's maximum value of y
///               ###
///               %unsigned 12 in_max_y                  0x3FF
///               %%        20         # Stuffing bits...
///     @ 0x00020 out_min_y            (P)
///               ###
///               * output data clamping's minimum value of y
///               ###
///               %unsigned 12 out_min_y                 0x0
///               %%        20         # Stuffing bits...
///     @ 0x00024 out_max_y            (P)
///               ###
///               * output data clamping's maximum value of y
