//////
/// 
/// $INTERFACE HDMI_VOP                biu              (4,4)
///     ###
///     * Register specification of interface VOP
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 12 hdmi_cblank               0x800
///                                    ###
///                                    * {HDMI_CBLANK_H[3:0],HDMI_CBLANK_L}
///                                    ###
///               %unsigned 3  hdmi_mode                 0x0
///                                    ###
///                                    * HDMI_MODE_REGS
///                                    ###
///               %unsigned 3  hdmi_sel                  0x0
///                                    ###
///                                    * HDMI_SEL_REGS
///                                    * 000: cpcbo(prog) is selected.
///                                    * 001: cpcb0(int) is selected.
///                                    * 010: cpcb1(prog) is selected.
///                                    * 011: No input
///                                    * 100: cpcb2(prog) input is selected.
///                                    * 101: cpcb2(int) input is selected.
///                                    * 110: Not used.
///                                    * 111: LVDS formatter output is selected. (LVDS_HDMI_DEBUG_CTRL should be set to 0x1)
///                                    ###
///               %unsigned 2  hdmi_align                0x0
///                                    ###
///                                    * 00 : (12-12-12) 8/10 bits LSB aligned
///                                    * 01 : (12-12-12) 8/10 bits MSB aligned
///                                    * 10 : 24/30 bits LSB aligned
///                                    * 11 : 24/30 bits MSB aligned
///                                    ###
///               %unsigned 3  hdmi_rnd                  0x0
///                                    ###
///                                    * 100 : Bypass
///                                    * 010 : 12 bits to 10 bits rounding
///                                    * 001 : 12 bits to 8 bits rounding
///                                    * Other values : output is zero
///                                    ###
///               %unsigned 6  hdmi_clkx_ctrl            0x4
///                                    ###
///                                    * [0] : clkSwitch : Selects between source clock and                             divider clock.   0 : Source clock, 1 : Divider clock
///                                    * [1] : clkD3Switch : Selects between non-divide by-3 vs divide by-3 clocks. 0 : Non div3 clock.
///                                    * 1: Div-3 clock.
///                                    * [2] : clkEn : Clock Enable
///                                    * 0: Disable the clock
///                                    * 1: Enable the clock
///                                    * [5:3] : Clock selection (divide by clock gen)
///                                    * 0x1 : d2
///                                    * 0x2 : d4
///                                    * 0x3 : d6
///                                    * 0x4 : d8
///                                    * 0x5 : d12
///                                    ###
///               %%        3          # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 1  ddc_fast_clk              0x1
///                                    ###
///                                    * 0: cfgClk (100MHz) is selected.
///                                    * 1: xtal_clk (25MHz) is selected.
///                                    ###
///               %unsigned 6  asd_clkx_ctrl             0x4
///                                    ###
///                                    * [0] : clkSwitch : Selects between source clock and                             divider clock.   0 : Source clock, 1 : Divider clock
///                                    * [1] : clkD3Switch : Selects between non-divide by-3 vs divide by-3 clocks. 0 : Non div3 clock.
///                                    * 1: Div-3 clock.
///                                    * [2] : clkEn : Clock Enable
///                                    * 0: Disable the clock
///                                    * 1: Enable the clock
///                                    * [5:3] : Clock selection (divide by clock gen)
///                                    * 0x1 : d2
///                                    * 0x2 : d4
///                                    * 0x3 : d6
///                                    * 0x4 : d8
///                                    * 0x5 : d12
///                                    ###
///               %%        25         # Stuffing bits...
///     @ 0x00008 CFG2                 (P)
///               %unsigned 12 td_lr_adj_pcnt            0x0
///                                    ###
///                                    * {LR_ADJ_PCNT_0[3:0],LR_ADJ_PCNT_0}
///                                    * LR-ID Adjust Pixel Count Register (LR-ID is delayed by number of clocks specified by this count from rising edge of VSYNC)
///                                    ###
///               %unsigned 12 td_lr_adj_lcnt            0x0
///                                    ###
///                                    * {LR_ADJ_LCNT_1[3:0],LR_ADJ_LCNT_0}
///                                    * LR-ID Adjust Line Count Register (LR-ID is delayed by number of lines specified by this count from rising edge of VSYNC)
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x0000C CFG3                 (P)
///               %unsigned 1  dither_bypass             0x1
///                                    ###
///                                    * Hard Bypass for DITHER. Write 0 to enable DITHER in HDMI PATH
///                                    ###
///               %unsigned 1  csc_bypass                0x0
///                                    ###
///                                    * Color Space Converter (CSC) in HDMI Path hard bypass bit. Write 1 to bypass CSC (also clock gate CSC block)
///                                    ###
///               %unsigned 1  dns444_422_bypass         0x0
///                                    ###
///                                    * DNS 444-to-422 in HDMI Path hard bypass. Write 1 to bypass DNS (444-to-422) (also clock gate DNS block)
///                                    ###
///               %unsigned 1  dns422_420_bypass         0x0
///                                    ###
///                                    * DNS 422-to-420 in HDMI Path hard bypass. Write 1 to bypass DNS (422-to-420) (also clock gate DNS block)
///                                    ###
///               %unsigned 1  dither_inctrl             0x0
///                                    ###
///                                    * Input data control for Dither.
///                                    * [0] – CSC output is selected as input to dither
///                                    * [1] – CSC input is selected as input to dither (CSC bypassed)
///                                    ###
///               %unsigned 6  input_swap_sel            0x24
///                                    ###
///                                    * [1:0] - 0: Will select B data
///                                    * 1: Will select G data
///                                    * else: Will select R data
///                                    * [3:2] - 0: Will select B data
///                                    * 1: Will select G data
///                                    * else: Will select R data
///                                    * [5:4] - 0: Will select B data
///                                    * 1: Will select G data
///                                    * else: Will select R data
///                                    ###
///               %%        21         # Stuffing bits...
///     @ 0x00010 CFG4                 (P)
///               %unsigned 1  DB_ocsc_bypass            0x0
///               %unsigned 1  DB_edr_hdmi_bypass        0x0
///               %unsigned 1  DB_dither_bypass          0x0
///               %unsigned 1  ClampMap_bypass           0x0
///               %unsigned 1  LDC_bypass                0x1
///                                    ###
///                                    * 0: enable, 1: bypass
///                                    ###
///               %unsigned 1  DB_edrhdmi_dither_sel     0x0
///                                    ###
///                                    * 0: edr HDMI path, 1: DB dither path
///                                    ###
///               %unsigned 1  edr_dns_sel               0x0
///                                    ###
///                                    * 1: Dolby EDR path, 0: DNS 422to420 path
///                                    ###
///               %unsigned 1  OfflineRd_ocsc_sel        0x0
///                                    ###
///                                    * 1: UPS Offline Read path, 0: OCSC output path
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x00014 CFG5                 (P-)
///               %unsigned 1  start                     0x0
///                                    ###
///                                    * 1: start, 0: don't start
///                                    ###
///               %unsigned 1  clear                     0x0
///                                    ###
///                                    * 1: clear, 0: don't clear
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x00018 CFG6                 (P)
///               %unsigned 32 inPixTot                  0x64
///                                    ###
///                                    * Total number of pixels
///                                    ###
///     @ 0x0001C CFG7                 (P)
///               %unsigned 1  tg_clken                  0x0
///                                    ###
///                                    * Clock enable for display TG.
///                                    ###
///               %unsigned 1  FifoSts_ctrl              0x0
///                                    ###
///                                    * Fifo status control register. Write 1 to make vop clock enable independent of flow control
///                                    ###
///               %unsigned 1  tg_clken_ctrl             0x1
///                                    ###
///                                    * Clock enable control register for display TG.
///                                    * Default 1. Write 0 to make vop clock enable independent of input FIFO empty status.
///                                    ###
///               %unsigned 1  ldcWr_ctrl                0x0
///                                    ###
///                                    * Ldc write control register for clock enable generation.
///                                    * Default 0. Write 1 to make vop clock enable dependent of LDC write client status.
///                                    ###
///               %unsigned 2  hdmitx_mode               0x2
///                                    ###
///                                    * Mode selection register used for 420 input for HDMITX
///                                    ###
///               %unsigned 1  hdmitx_fix_clr_en         0x0
///                                    ###
///                                    * Fix color enable register used for 420 input for HDMITX
///                                    ###
///               %unsigned 4  hdmitx_clr_depth          0x6
///                                    ###
///                                    * Color depth register used for 420 input for HDMITX
///                                    * 4 : 8 bit deep color mode
///                                    * 5 : 10 bit deep color mode
///                                    * 6 : 12 bit deep color mode
///                                    ###
///               %unsigned 1  hdmitx_420_inp            0x0
///                                    ###
///                                    * 0: default means bypass 420 mapping block (other cases)
///                                    * 1: enable if require 420 input for HDMITX (pixel clock vClk0/cpcb0Clk frequency should be divide by 2).
///                                    ###
///               %unsigned 1  FifoSts_ctrl1             0x0
///                                    ###
///                                    * 1: enable if DP1 path used for DSI-MIPI.
///                                    * 0: disable if DP1 path not used for DSI-MIPI.
///                                    ###
///               %%        19         # Stuffing bits...
///     @ 0x00020 CFG8                 (P)
///               %unsigned 13 PixlineTot                0x64
///                                    ###
///                                    * Total number of pixels in a line.
///                                    ###
///               %unsigned 1  nstdres_en                0x0
///                                    ###
///                                    * Non standard enable register.
///                                    ###
///               %unsigned 4  flushCntReg               0x5
///                                    ###
///                                    * Flush count register.
///                                    ###
///               %unsigned 1  edrHDMI_ctrl              0x0
///                                    ###
///                                    * EDR HDMI control register for clock enable generation.
///                                    * Write 1 when edr hdmi meta IP is in path
///                                    ###
///               %%        13         # Stuffing bits...
///     @ 0x00024 CFG9                 (P-)
///               %unsigned 1  edrClient_start           0x0
///                                    ###
///                                    * 1: start, 0: don't start
///                                    ###
///               %unsigned 1  edrClient_clear           0x0
///                                    ###
///                                    * 1: clear, 0: don't clear
///                                    ###
///               %unsigned 1  edrHdr10pHDMI_clear       0x0
///                                    ###
///                                    * Register used to clear or reset counter
///                                    * 1: clear, 0: don't clear
///                                    ###
///               %unsigned 1  hdr10pHDMI_clear          0x0
///                                    ###
///                                    * Register used to clear HDR10p HDMI ASYNC FIFO
///                                    * 1: clear, 0: don't clear
///                                    ###
///               %%        28         # Stuffing bits...
///     @ 0x00028 CFG10                (P)
///               %unsigned 32 edrClient_wordTot         0x64
///                                    ###
///                                    * Total number of word total.
///                                    ###
///     @ 0x0002C                      (P)
///     # 0x0002C DITHER               
///               $DITHER              DITHER            REG          
///                                    ###
///                                    * DITHER register definitions
///                                    ###
///     @ 0x00030                      (P)
///     # 0x00030 HDMI_CSC             
///               $CSC_C17O24          HDMI_CSC          REG          
///     @ 0x00060                      (P)
///     # 0x00060 DNS422_420           
///               $DNS422_420          DNS422_420        REG          
///                                    ###
///                                    * DNS422to420 register definitions
///                                    ###
///     @ 0x00068                      (P)
///     # 0x00068 ClampMap             
///               $ClampMap            ClampMap          REG          
///                                    ###
///                                    * Register Description for Range Clamping and Mapping IP
///                                    ###
///     @ 0x000AC                      (P)
///     # 0x000AC SRAMPWR_DNS422_420   
///               $SRAMPWR             SRAMPWR_DNS422_420 REG          
///                                    ###
///                                    * Power control register for DNS422_420 in VOP (DP1) path.
///                                    ###
///     @ 0x000B0                      (P)
///     # 0x000B0 SRAMPWR_UFPFIFO_1    
///               $SRAMPWR             SRAMPWR_UFPFIFO_1 REG          
///                                    ###
///                                    * Power control register for UFP FIFO_1 in VOP (DP1) path.
///                                    ###
///     @ 0x000B4 ldcW                 (P-)
///               %unsigned 1  start                     0x0
///               %unsigned 1  clear                     0x0
///                                    ###
///                                    * Start bit for the respective clients.
///                                    * 0 – No effect on hardware.
///                                    * 1 – start the client.
///                                    * The write 1 to this register is used to kick the hardware.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x000B8 ldcW_pix             (P)
///               %unsigned 32 tot                       0x64
///                                    ###
///                                    * Specifies the total number of pixels expected from LDC to its write client. This is used to generate flush in ldcW client to write the partially formed 64-bit data (if any) to DDR of histogram data
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:     188B, bits:     692b, padding:     0B
