//////
/// 
/// $INTERFACE VOP                     biu              (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000 CTRL                 (P)
///               %unsigned 1  asd_vopEnb                0x1
///               %unsigned 1  hdmi_vopEnb               0x1
///               %unsigned 1  lvds0_vopEnb              0x1
///               %unsigned 1  lvds1_vopEnb              0x1
///               %unsigned 1  videoEnc_Enb              0x1
///               %unsigned 1  hdmiTx_Enb                0x1
///               %unsigned 1  ttl24_vopEnb              0x1
///               %unsigned 1  ttl30_vopEnb              0x1
///               %unsigned 1  ahd_in_ctrl               0x0
///                                    ###
///                                    * Input Control for AHD. Write 1 for selecting YUV data
///                                    ###
///               %unsigned 1  dpEnb                     0x1
///                                    ###
///                                    * Enable register for output (either hdmi vop or vop2)
///                                    ###
///               %unsigned 1  dp_output_sel             0x0
///                                    ###
///                                    * Static Register used for FPGA purpose to select DP1 and DP2 path.
///                                    * 0: hdmi vop path (DP1 path) (default path)
///                                    * 1 : vop2 path (DP2 path)
///                                    ###
///               %unsigned 2  align_fpga_regs           0x0
///                                    ###
///                                    * 00 : (12-12-12) 8/10 bits LSB aligned
///                                    * 01 : (12-12-12) 8/10 bits MSB aligned
///                                    * 10 : 24/30 bits LSB aligned
///                                    * 11 : 24/30 bits MSB aligned
///                                    ###
///               %unsigned 3  rnd_fpga_regs             0x0
///                                    ###
///                                    * 100 : Bypass
///                                    * 010 : 12 bits to 10 bits rounding
///                                    * 001 : 12 bits to 8 bits rounding
///                                    * Other values : output is zero
///                                    ###
///               %unsigned 3  mode_ctrl_fpga_regs       0x0
///                                    ###
///                                    * Register used for FPGA
///                                    * [0] : to select between HS (value 1) and HDE (value 0)
///                                    * [1] : to select between VS (value 1) and VDE (value 0)
///                                    * [2] : to select between DE (value 1) and FLD (value 0)
///                                    ###
///               %unsigned 1  mode_sel_fpga_regs        0x0
///                                    ###
///                                    * Register used for FPGA purpose to select between RGB444 and YUV422.
///                                    * 0: YUV422 (default path)
///                                    * 1 : RGB444
///                                    ###
///               %unsigned 1  pol_ctrl_fpga_regs        
///                                    ###
///                                    * Clock polarity control register.
///                                    ###
///               %unsigned 4  dly_ctrl_fpga_regs        
///                                    ###
///                                    * Clock delay control register.
///                                    ###
///               %%        7          # Stuffing bits...
///     @ 0x00004 ASD                  (P)
///               %unsigned 3  sel                       0x4
///               %unsigned 1  trig                      0x1
///               %unsigned 8  nof                       0x2
///               %%        20         # Stuffing bits...
///     @ 0x00008 AHD                  (P)
///               %unsigned 3  sel                       0x4
///               %unsigned 1  trig                      0x1
///               %unsigned 8  nof                       0x2
///               %%        20         # Stuffing bits...
///     @ 0x0000C TTL24                (P)
///               %unsigned 3  sel                       0x0
///               %unsigned 12 cblank                    0x0
///               %unsigned 1  mode                      0x0
///               %unsigned 1  trig                      0x1
///               %unsigned 8  nof                       0x2
///               %unsigned 2  c656_saturate             0x0
///               %%        5          # Stuffing bits...
///     @ 0x00010 TTL24_CTRL           (P)
///               %unsigned 6  regs                      0x0
///               %%        26         # Stuffing bits...
///     @ 0x00014 TTL24_DELAY          (P)
///               %unsigned 4  regs                      0x0
///               %%        28         # Stuffing bits...
///     @ 0x00018 TTL30                (P)
///               %unsigned 3  sel                       0x0
///               %unsigned 12 cblank                    0x0
///               %unsigned 1  mode                      0x0
///               %unsigned 1  trig                      0x1
///               %unsigned 8  nof                       0x2
///               %unsigned 2  saturate                  0x0
///               %%        5          # Stuffing bits...
///     @ 0x0001C TTL30_CTRL           (P)
///               %unsigned 6  regs                      0x0
///               %%        26         # Stuffing bits...
///     @ 0x00020 TTL30_DELAY          (P)
///               %unsigned 4  regs                      0x0
///               %%        28         # Stuffing bits...
///     @ 0x00024 TD_HDMI              (P)
///               %unsigned 1  trig                      0x1
///               %unsigned 8  nof                       0x2
///               %%        23         # Stuffing bits...
///     @ 0x00028 TD_HDMI_CTRL         (P)
///               %unsigned 8  ctrl0                     0x0
///               %unsigned 8  ctrl1                     0x0
///               %%        16         # Stuffing bits...
///     @ 0x0002C TD_HDMI_UDATA        (P)
///               %unsigned 12 regs                      0x0
///               %%        20         # Stuffing bits...
///     @ 0x00030 TD_HDMI_MDATA        (P)
///               %unsigned 12 regs                      0x0
///               %%        20         # Stuffing bits...
///     @ 0x00034 TD_HDMI_LDATA        (P)
///               %unsigned 12 regs                      0x0
///               %%        20         # Stuffing bits...
///     @ 0x00038 CLKPOL               (P)
///               %unsigned 2  ctrl                      0x0
///               %%        30         # Stuffing bits...
///     @ 0x0003C ASD_SIG_STS          (R-)
///               %unsigned 32 regs                      0x0
///     @ 0x00040 ASD_STS              (R-)
///               %unsigned 1  armed                     0x0
///               %unsigned 1  err                       0x0
///               %unsigned 1  done                      0x0
///               %%        29         # Stuffing bits...
///     @ 0x00044 AHD_SIG_STS          (R-)
///               %unsigned 32 regs                      0x0
///     @ 0x00048 AHD_STS              (R-)
///               %unsigned 1  armed                     0x0
///               %unsigned 1  err                       0x0
///               %unsigned 1  done                      0x0
///               %%        29         # Stuffing bits...
///     @ 0x0004C TTL24_SIG_STS        (R-)
///               %unsigned 32 regs                      0x0
///     @ 0x00050 TTL24_STS            (R-)
///               %unsigned 1  armed                     0x0
///               %unsigned 1  err                       0x0
///               %unsigned 1  done                      0x0
///               %%        29         # Stuffing bits...
///     @ 0x00054 TTL30_SIG_STS        (R-)
///               %unsigned 32 regs                      0x0
///     @ 0x00058 TTL30_STS            (R-)
///               %unsigned 1  armed                     0x0
///               %unsigned 1  err                       0x0
///               %unsigned 1  done                      0x0
///               %%        29         # Stuffing bits...
///     @ 0x0005C HDMI_SIG_STS         (R-)
///               %unsigned 32 regs                      0x0
///     @ 0x00060 HDMI_STS             (R-)
///               %unsigned 1  armed                     0x0
///               %unsigned 1  err                       0x0
///               %unsigned 1  done                      0x0
///               %unsigned 2  l_r_o_e_view_final        0x0
///               %%        27         # Stuffing bits...
///     @ 0x00064 DAC_RAMP_CTRL        (P)
///               %unsigned 12 start                     0x0
///                                    ###
///                                    * Start value for the Ramp generator.
///                                    * Ramp starts at “start” code and stops at “stop” code. It increases by 1 from “start”, reaches “stop” and then decrements by 1 to reach start – this repeats. DAC input stays at each code for step+1 no. of DAC clock cycles.
///                                    ###
///               %unsigned 12 stop                      0xFFF
///                                    ###
///                                    * Stop value for the Ramp generator
///                                    ###
///               %unsigned 8  step                      0x0
///                                    ###
///                                    * Step value for the Ramp generator. The code to the DAC is changed after (step+1) no. of DAC clock cycles.
///                                    ###
///     @ 0x00068 DAC_TEST_CTRL        (P)
///               %unsigned 2  sel                       0x0
///                                    ###
///                                    * Controls the data driven to all 6 VDACs.
///                                    * 00: selects Video encoder output
///                                    * 01: selects ramp generator output (for ATE)
///                                    * 10: selects DRAM data (sine-wave)
///                                    * When, sel=10, DiR1 dHub channel is used for VDAC test purpose. Software should be aware of this.
///                                    * Each 16-bit is considered as one code (though only 12-bit of it is used). Software should prepare the data in DRAM in little-endian order and start the DiR1 dHub channel. It may use self-loop feature of dHub to repetitively fetch the same buffer.
///                                    * 11: reserved
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x0006C SD_TT_CLIENT         (P)
///               %unsigned 1  enable                    0x0
///               %unsigned 1  clear                     0x0
///                                    ###
///                                    * Enable bit for the SD TTXT (teletext) read client
///                                    * 0 – Don't request data from dHub
///                                    * 1 – start requesting data from dHub.
///                                    * SW typically needs to enable it only at the start as part of initialization.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x00070 SD_TT_BYTE           (P)
///               %unsigned 32 tot                       0x0
///                                    ###
///                                    * Specifies the total number of (TT bytes per line or per frame) -1; used by HW to flush the partially consumed 64-bit data in TT read client.
///                                    * Whether this number is per line or per frame, depends on the TT packet data packing in DRAM.
///                                    * If the SW prefers to pack the TT bytes of adjacent packets with no holes, then program “tot” = TT bytes per frame
///                                    * If the SW prefers to start each TT packet on 64-byte boundary, then program “tot” = TT bytes per line.
///                                    ###
///     @ 0x00074 SD_TT_TEST           (P)
///               %unsigned 8  data                      0x0
///                                    ###
///                                    * 8-bit data to be sent to encoder as Teletext data.
///                                    ###
///               %unsigned 1  sel                       0x0
///                                    ###
///                                    * 1: selects above “data” as TT input to encoder. Should only be used for Test purposes.
///                                    * 0: TT data comes from DRAM.
///                                    ###
///               %%        23         # Stuffing bits...
///     @ 0x00078 enc_hsvs_sel         (P)
///               %unsigned 1  sel                       0x1
///                                    ###
///                                    * Selects which DAC channel's HS/VS to output
///                                    * 0 : selects HS/VS of DAC channel0 (DAC0,1,2)
///                                    * 1: selects HS/VS of DAC channel 1(DAC3,4,5)
///                                    ###
///               %%        31         # Stuffing bits...
///     @ 0x0007C LVDS_HDMI_DEBUG      (P)
///               %unsigned 2  CTRL                      0x1
///                                    ###
///                                    * If 0, HDMI_VOP data output is passed onto data6_i and corresponding ctrl signals on ctrl6_i.
///                                    * If 1 , LVDS_VOP0 data output before lvbo_tx is passed onto data6_i and corresponding ctrl signals on ctrl6_i.
///                                    * If 2 , LVDS_VOP1 data output before lvbo_tx is passed onto data6_i and corresponding ctrl signals on ctrl6_i.
///                                    ###
///               %%        30         # Stuffing bits...
///     @ 0x00080                      (P)
///     # 0x00080 HDMI_VOP             
///               $HDMI_VOP            HDMI_VOP          REG          
///                                    ###
///                                    * HDMI VOP register descriptions
///                                    ###
///     @ 0x0013C                      (P)
///     # 0x0013C OCSC                 
///               $VPP_GFX_VOP_REG0    OCSC              REG
///                                    ###
///                                    * Output VOP CSC register descriptions
///                                    ###
///     @ 0x001D0                      (P)
///     # 0x001D0 EDRHDMI              
///               $VPP_GFX_VOP_REG1    EDRHDMI           REG
///                                    ###
///                                    * EDR HDMI register descriptions
///                                    ###
///     @ 0x001D4                      (P)
///     # 0x001D4 DTG                  
///               $DTG                 DTG               REG          
///                                    ###
///                                    * Display TG register descriptions
///                                    ###
///     @ 0x0029C                      (P)
///     # 0x0029C DB_DITHERING         
///               $VPP_GFX_VOP_REG2    DB_DITHERING      REG
///                                    ###
///                                    * Dolby dither register descriptions
///                                    ###
///     @ 0x002A4                      (P)
///     # 0x002A4 VRR                  
///               $VRR                 VRR               REG          
///                                    ###
///                                    * VRR timing generation registers
///                                    * End of VOP definition.
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:     788B, bits:    3656b, padding:     0B
